@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService service;
    public OrderController(OrderService service) { this.service = service; }

    @GetMapping("/{id}")
    public OrderView get(@PathVariable long id) {
        return service.find(id);
    }
}

public record CreateOrderRequest(
        @NotNull Long userId,
        @NotEmpty List<@Valid Item> items) {}

@PostMapping
public OrderView create(@Valid @RequestBody CreateOrderRequest req) {
    return service.create(req);
}

@Service
public class OrderService {
    private final OrderMapper mapper;
    public OrderService(OrderMapper mapper) { this.mapper = mapper; }

    @Transactional(rollbackFor = Exception.class)
    public OrderView create(CreateOrderRequest req) {
        long id = mapper.insert(req);
        return mapper.findById(id);
    }
}

@Mapper
public interface OrderMapper {
    @Select("select id, user_id, amount from orders where id = #{id}")
    OrderRow findById(long id);
}
